 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_window_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_window_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil51500.btn_window_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_excelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_excelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_excelUpload",
        method: "post",
        action: "/listInvstg/listPrelmInvstg.do?method=fncContnExcelUploadData",
        ref: "dma_excelUploadReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil51500.tx_fn_excelUpload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.excelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.excelUpload = async function () {
    /* sdd-asis-lifecycle:begin fn_excelUpload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.popForm || { elements: [] });
    if (($c.util.getComponent('upd_fncContnAttachExcelfile').getValue() == null ? '' : String($c.util.getComponent('upd_fncContnAttachExcelfile').getValue())) === '') {
        await $c.win.alert("파일을 선택하세요.");
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_fncContnAttachExcelfile').getValue())) {
            await $c.win.alert("엑셀파일만 업로드 가능합니다. 다시 선택하세요.");
            return;
        }
    }
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        $c.util.getComponent("dialogLoading").setStyle("display", "");
        frm.action = "/listInvstg/listPrelmInvstg.do?method=fncContnExcelUploadData";
        frm.target = "iframe";
        await scwin.tx_fn_excelUpload();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileType
 * @author Inswave
 * @date 2026. 09. 29
 * @param filePath
 * @returns
 * @hidden N
*/
scwin.checkFileType = function (filePath) {
    /* sdd-asis-lifecycle:begin checkFileType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fileFormat = filePath.toLowerCase();
    if (fileFormat.indexOf(".xls") > -1) {
        return true;
    } else {
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setLoadDataPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param dataArr
 * @returns
