*/
scwin.setLoadDataPop = async function (dataArr) {
    /* sdd-asis-lifecycle:begin setLoadDataPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setLoadData === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setLoadData(dataArr) : void 0), $c.win.closePopup([dataArr]))) {
        await $c.win.alert('파일 업로드가 정상 처리되었습니다.\n - 항목별 값 확인 후 [저장] 버튼을 선택하세요.');
        $c.win.closePopup();
    } else {
        await $c.win.alert('재무사항 화면으로 데이터 처리시 오류가 발생했습니다.\n - 메뉴를 다시 선택하여 진행하세요.');
    }
    /* sdd-asis-lifecycle:end */
};
